/* Generated by engine/build-site.mjs — no dependencies, and nothing is requested at runtime. */
/* ══════════════════════════════════════════════ THE HOME PAGE (package HOME) ══
   Live search, composable facets and a sortable table, reshaping a list that is ALREADY FULLY IN
   THE HTML. Nothing here renders an episode; it only hides, reorders and annotates. Turn scripting
   off and every episode is still listed and still linked.

   ⛔ IT BAILS OUT ON THE OTHER PAGE THAT LOADS IT. A DOCUMENT PAGE WITH A TABLE OF CONTENTS loads
   this same file and has neither #q nor #grid, so the guard below returns before a single listener
   is attached — which leaves the table-of-contents observer further down the only thing that runs
   there. Nothing else loads it: episode index pages and TOC-less document pages ship no script at
   all, so the guard is the whole of the separation and has to stay.

   ⚠ THE COMMENT THIS REPLACES WAS FALSE, and it is worth saying why rather than just correcting it.
   It claimed the episode AND document pages loaded this file and bailed out of the guard. They
   loaded NOTHING — the page shell takes a scripts argument and no caller passed it — so the built
   document pages contained zero script tags, the TOC observer below had never executed since
   package SITE, and its ".toc a.on" rule was dead CSS. The comment described a wiring that did not
   exist, which is exactly how a feature stays broken: anyone auditing "does the scroll-spy run?"
   read this and stopped. Document pages with a TOC are wired for real now. */
/* WALL — live search + category filters, reshaping a list that is already fully in the HTML. */
(function () {
  var EPS = window.__EPISODES__ || [];
  var by = {};
  for (var i = 0; i < EPS.length; i++) by[EPS[i].s] = EPS[i];

  var q = document.getElementById("q");
  var clearBtn = document.getElementById("clear");
  var grid = document.getElementById("grid");
  var countEl = document.getElementById("count");
  var emptyEl = document.getElementById("empty");
  var emptySay = document.getElementById("empty-say");
  var emptyBtn = document.getElementById("empty-clear");
  var record = document.getElementById("record-tile");
  var tiles = [].slice.call(document.querySelectorAll(".tile[data-slug]"));
  var rows = [].slice.call(document.querySelectorAll("tr[data-slug]"));
  var chips = [].slice.call(document.querySelectorAll(".chip"));
  var heads = [].slice.call(document.querySelectorAll(".dense th[aria-sort]"));
  if (!q || !grid) return;

  var TOTAL = tiles.length;
  var BASE = countEl.innerHTML;
  var cat = "all";
  var flag = "";
  var clearWhat = "query";

  /* Each chip's own words, taken once — before any count is rewritten over them — so the empty
     state can name the filter that emptied the page in the same language the chip does. */
  var CATLABEL = {};
  for (var li = 0; li < chips.length; li++) {
    if (chips[li].hasAttribute("data-flag")) continue;
    CATLABEL[chips[li].getAttribute("data-cat")] =
      (chips[li].textContent || "").replace(/\s*\d+\s*$/, "").trim();
  }

  var DOC = { brief: "The research", sources: "Sources", "factcheck-log": "Fact-check log", transcript: "Transcript" };

  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  function rx(t) { return new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig"); }
  function mark(text, terms) {
    var out = esc(text);
    for (var i = 0; i < terms.length; i++) out = out.replace(rx(terms[i]), "<mark>$1</mark>");
    return out;
  }

  /* Everything about one episode, flattened once, so keystrokes stay cheap. */
  var blob = {};
  for (var k = 0; k < EPS.length; k++) {
    var e = EPS[k];
    var parts = [e.t, e.b, e.q, e.c, e.fc, "ep" + e.n, (e.g || []).join(" "), (e.p || []).join(" ")];
    for (var d = 0; d < (e.d || []).length; d++) {
      parts.push(e.d[d][1]);
      var hs = e.d[d][2] || [];
      for (var h = 0; h < hs.length; h++) parts.push(hs[h][1]);
      var cl = e.d[d][3] || [];
      for (var c = 0; c < cl.length; c++) parts.push(cl[c]);
    }
    blob[e.s] = parts.join(" \u2022 ").toLowerCase();
  }

  /* Deep hits — the sections and fact-checked claims that matched, linked to their anchors. */
  function hitsFor(e, terms) {
    var out = [];
    for (var d = 0; d < (e.d || []).length; d++) {
      var stem = e.d[d][0], title = DOC[stem] || e.d[d][1];
      var hs = e.d[d][2] || [];
      for (var h = 0; h < hs.length; h++) {
        if (any(hs[h][1], terms)) out.push({ w: title, t: hs[h][1], href: e.s + "/" + stem + ".html#" + hs[h][0] });
      }
      var cl = e.d[d][3] || [];
      for (var c = 0; c < cl.length; c++) {
        if (any(cl[c], terms)) out.push({ w: title + " · claim", t: cl[c], href: e.s + "/" + stem + ".html" });
      }
    }
    return out;
  }
  /* An episode has to satisfy every term (AND) to survive the filter; a single line inside the
     record only has to carry one of them, or a two-word query would surface nothing at all. */
  function matches(s, terms) {
    var l = String(s).toLowerCase();
    for (var i = 0; i < terms.length; i++) if (l.indexOf(terms[i]) === -1) return false;
    return true;
  }
  function any(s, terms) {
    var l = String(s).toLowerCase();
    for (var i = 0; i < terms.length; i++) if (l.indexOf(terms[i]) > -1) return true;
    return false;
  }

  function score(e, terms, hits) {
    var s = 0, t = (e.t || "").toLowerCase(), qq = ((e.q || "") + " " + (e.b || "")).toLowerCase();
    for (var i = 0; i < terms.length; i++) {
      if (t.indexOf(terms[i]) > -1) s += 100;
      if (qq.indexOf(terms[i]) > -1) s += 40;
      if ((e.g || []).join(" ").toLowerCase().indexOf(terms[i]) > -1) s += 30;
    }
    return s + Math.min(hits.length, 12) * 6 + (e.n || 0) * 0.1;
  }

  /* One pass over the catalogue per keystroke, kept as a table the chips and the empty state can
     both read. The bug this replaces was not a wrong number, it was a number nobody recomputed:
     the counts were baked at build time, so "Tech policy 3" went on advertising 3 while the query
     had left it holding none. A facet that states a total it cannot deliver is worse than one that
     states nothing, because it is the one part of the interface a visitor uses to decide where to
     look next. */
  var TEXTOK = {}, CORR = {}, CATOF = {};
  for (var ti = 0; ti < tiles.length; ti++) {
    var t0 = tiles[ti], s0 = t0.getAttribute("data-slug");
    CORR[s0] = Number(t0.getAttribute("data-corrected")) > 0;
    CATOF[s0] = t0.getAttribute("data-cat");
  }

  /* What a chip WOULD yield if it were the live filter: its own facet against the current query and
     the OTHER facet, never against itself. Counting a chip with itself already applied is how a
     filter bar ends up telling you every category has the number you are already looking at.

     ROUND 8 — THE AXIS BUG. This function was right and was being contradicted. It intersects the
     chip's facet with the OTHER facet, which is what apply() does when it decides which tiles
     survive — but the CLICK handler REPLACED that facet (a category click set flag="", the
     corrections chip set cat="all"), so every count was honest against the query and a lie against
     the filter. Measured live: corrections on, query empty, the bar reads "All 2" and clicking All
     delivers 5. The fix is in the handler, and it is the direction that keeps this logic — the two
     facets COMPOSE now, so a count and the click that redeems it describe the same set. */
  function chipCount(chip) {
    var isFlag = chip.hasAttribute("data-flag"), want = chip.getAttribute("data-cat"), n = 0;
    for (var s in TEXTOK) {
      if (!TEXTOK[s]) continue;
      if (isFlag) {
        if (!CORR[s]) continue;
        if (cat !== "all" && CATOF[s] !== cat) continue;
      } else {
        if (want !== "all" && CATOF[s] !== want) continue;
        if (flag && !CORR[s]) continue;
      }
      n++;
    }
    return n;
  }

  function apply() {
    var raw = q.value.trim();
    var terms = raw.toLowerCase().split(/\s+/).filter(Boolean);
    var active = terms.length > 0;
    var shown = 0, deep = 0, textHits = 0;

    for (var s1 in CATOF) {
      TEXTOK[s1] = !active || matches(blob[s1] || "", terms);
      if (TEXTOK[s1]) textHits++;
    }

    for (var i = 0; i < tiles.length; i++) {
      var tile = tiles[i], slug = tile.getAttribute("data-slug"), e = by[slug] || {};
      var okCat = cat === "all" || CATOF[slug] === cat;
      var okFlag = !flag || CORR[slug];
      var okText = TEXTOK[slug];
      var on = okCat && okFlag && okText;

      var hits = active && on ? hitsFor(e, terms) : [];
      deep += hits.length;

      tile.classList.toggle("is-out", !on);
      tile.style.order = on && active ? String(1000 - Math.round(score(e, terms, hits))) : "";

      var box = tile.querySelector(".hits");
      if (box) {
        if (hits.length) {
          var html = "";
          for (var j = 0; j < Math.min(hits.length, 4); j++)
            html += '<li><a href="' + hits[j].href + '"><span class="where">' + esc(hits[j].w) + "</span>" + mark(hits[j].t, terms) + "</a></li>";
          if (hits.length > 4) html += '<li class="more">+ ' + (hits.length - 4) + " more inside the record</li>";
          box.innerHTML = html;
          box.hidden = false;
        } else { box.innerHTML = ""; box.hidden = true; }
      }
      if (on) shown++;
    }

    for (var r = 0; r < rows.length; r++) {
      var row = rows[r], rs = row.getAttribute("data-slug");
      var rOk = (cat === "all" || CATOF[rs] === cat) && (!flag || CORR[rs]) && TEXTOK[rs];
      row.classList.toggle("is-out", !rOk);
    }

    /* Every chip is re-counted against the live query on every keystroke. */
    for (var ci = 0; ci < chips.length; ci++) {
      var chip = chips[ci], b = chip.querySelector("b"), n = chipCount(chip);
      if (b) b.textContent = String(n);
      chip.classList.toggle("is-none", n === 0);
      if (n === 0) {
        chip.setAttribute("aria-disabled", "true");
        chip.setAttribute("title", active ? "No episode here matches " + raw : "Nothing here under the current filter");
      } else {
        chip.removeAttribute("aria-disabled");
        chip.removeAttribute("title");
      }
    }

    var filtering = active || cat !== "all" || !!flag;
    grid.classList.toggle("is-filtered", filtering);
    // A wall of one brick is not a wall. Narrow results widen so a single survivor reads as a
    // result rather than as a hole where four episodes used to be.
    grid.setAttribute("data-n", filtering ? String(shown) : "");
    if (record) record.classList.toggle("is-out", filtering);
    if (clearBtn) clearBtn.hidden = !raw;

    /* Name what actually emptied the page. If the query still matches episodes and a filter is what
       is hiding them, saying "nothing matches nuclear" is false — the record does match, and the
       visitor is one click from it. So the sentence counts the real matches, names the filter that
       is excluding them, and the button clears THAT and keeps the query. */
    if (emptyEl) {
      emptyEl.hidden = shown > 0;
      if (!emptyEl.hidden && emptySay && emptyBtn) {
        var bits = [];
        if (cat !== "all") bits.push("in " + (CATLABEL[cat] || cat));
        if (flag) bits.push("with a correction");
        var what = bits.join(" ");
        if (what && textHits > 0) {
          clearWhat = "filter";
          emptySay.innerHTML = active
            ? "<b>" + textHits + "</b> episode" + (textHits === 1 ? "" : "s") + " match <b>" + esc(raw) +
              "</b> \u2014 none of them " + esc(what) + "."
            : "No episode " + esc(what) + ".";
          emptyBtn.textContent = flag && cat === "all" ? "Clear the corrections filter"
            : !flag ? "Clear the " + (CATLABEL[cat] || cat) + " filter" : "Clear both filters";
        } else if (active) {
          clearWhat = "query";
          emptySay.innerHTML = "Nothing in the record matches <b>" + esc(raw) + "</b>.";
          emptyBtn.textContent = "Clear the search";
        } else {
          clearWhat = "both";
          emptySay.textContent = "Nothing here under the current search and filters.";
          emptyBtn.textContent = "Start over";
        }
      }
    }

    if (!filtering) countEl.innerHTML = BASE;
    // "1 of 1 episodes" — the same hard-coded plural the build side carried, one layer down. TOTAL is
    // the number of tiles on the page, which is 1 on the first publish (build-site --only <slug>).
    else countEl.innerHTML = "<b>" + shown + "</b> of <b>" + TOTAL + "</b> episode" + (TOTAL === 1 ? "" : "s") +
      // Only while something is on screen. "deep" counts lines inside the episodes that SURVIVED the
      // filter, so on an emptied page it reads "0 matches inside the record" next to an empty state
      // saying two episodes match — the same lie, one line over.
      (active && shown ? " · <b>" + deep + "</b> match" + (deep === 1 ? "" : "es") + " inside the record" : "");
  }

  q.addEventListener("input", apply);
  q.addEventListener("search", apply);
  if (clearBtn) clearBtn.addEventListener("click", function () { q.value = ""; q.focus(); apply(); });
  if (emptyBtn)
    emptyBtn.addEventListener("click", function () {
      if (clearWhat !== "filter") q.value = "";
      if (clearWhat !== "query") { cat = "all"; flag = ""; }
      sync(); apply(); q.focus();
    });

  /* The two facets are independent, so their lit states are independent too. This used to read
     "(!flag && cat matches)", which blanked every category chip the moment the corrections filter
     came on — the interface then showed no category selected while a category was still, in fact,
     filtering the grid. Same bug as the counts, one line over. */
  function sync() {
    for (var i = 0; i < chips.length; i++) {
      var c = chips[i];
      var on = c.hasAttribute("data-flag") ? !!flag : c.getAttribute("data-cat") === cat;
      c.classList.toggle("is-on", on);
      c.setAttribute("aria-pressed", on ? "true" : "false");
    }
  }
  for (var ck = 0; ck < chips.length; ck++) {
    chips[ck].addEventListener("click", function () {
      // A chip standing at zero is not a route anywhere — clicking it used to land on an empty page
      // that blamed the search. "All" and the chip already on are never blocked, because those are
      // the two clicks that get you OUT of an empty result.
      if (this.classList.contains("is-none") && !this.classList.contains("is-on") &&
          this.getAttribute("data-cat") !== "all") return;
      // ROUND 8 — THE FACETS COMPOSE. Neither click clears the other axis any more: the corrections
      // toggle no longer resets the category and a category no longer drops the corrections filter.
      // That is what makes every advertised count true, because chipCount() has always measured the
      // intersection and apply() has always rendered it — the handler was the only place that
      // thought these were two radio groups. "All" is the category axis's own reset and keeps the
      // flag, which is exactly the "All 2" its count now promises.
      if (this.hasAttribute("data-flag")) flag = flag ? "" : "corrected";
      else cat = this.getAttribute("data-cat");
      sync(); apply();
    });
  }
  sync();

  /* ---- sorting the dense table ---------------------------------------------------------------
     The table is the view someone switches to in order to work the data, and until now it could not
     answer the first question anyone brings to it — which episode got the most wrong. It sorts on
     the four numeric columns, off values carried on the row rather than off cell text, and it never
     touches the query or the category: reordering happens by re-appending the same row elements, so
     whatever "is-out" marked hidden stays hidden and comes back in the new order. */
  var tbody = rows.length ? rows[0].parentNode : null;
  var sortKey = "n", sortDir = -1;
  /* ROUND 8 — the same four orderings, stated a second time above the scroller. At 390 the table is
     1347px inside a 360px scroller, so three of the four column headers are off-screen at rest and
     nothing on the page says they exist. Both control sets drive this one state and both are
     repainted from it, so they can never disagree about what the table is currently sorted by. */
  var pills = [].slice.call(document.querySelectorAll(".sortbar .sb"));

  function sortRows() {
    if (!tbody) return;
    var list = rows.slice().sort(function (a, b) {
      var d = (Number(a.getAttribute("data-" + sortKey)) - Number(b.getAttribute("data-" + sortKey))) * sortDir;
      // Ties fall back to newest-first, so equal claim counts never shuffle between clicks.
      return d || Number(b.getAttribute("data-n")) - Number(a.getAttribute("data-n"));
    });
    var frag = document.createDocumentFragment();
    for (var i = 0; i < list.length; i++) frag.appendChild(list[i]);
    tbody.appendChild(frag);
    for (var h = 0; h < heads.length; h++) {
      var btn = heads[h].querySelector(".sort");
      var k = btn ? btn.getAttribute("data-sort") : "";
      heads[h].setAttribute("aria-sort", k === sortKey ? (sortDir < 0 ? "descending" : "ascending") : "none");
    }
    for (var p = 0; p < pills.length; p++) {
      var on = pills[p].getAttribute("data-sort") === sortKey;
      pills[p].classList.toggle("is-on", on);
      // The pill says WHICH WAY as well as which key — on a small screen it is the only thing that
      // can, because the column header carrying the arrow is off to the right.
      pills[p].classList.toggle("asc", on && sortDir > 0);
      pills[p].setAttribute("aria-pressed", on ? "true" : "false");
    }
  }

  // Same column flips direction; a new column opens on descending, because every one of these is a
  // "which is the most" question before it is a "which is the least" one.
  function sortOn(k) {
    if (k === sortKey) sortDir = -sortDir; else { sortKey = k; sortDir = -1; }
    sortRows();
  }
  function wireSort(btn) {
    if (!btn) return;
    btn.disabled = false; // inert in the markup; live only once this script has run
    btn.addEventListener("click", function () { sortOn(this.getAttribute("data-sort")); });
  }
  for (var hi = 0; hi < heads.length; hi++) wireSort(heads[hi].querySelector(".sort"));
  for (var pi = 0; pi < pills.length; pi++) wireSort(pills[pi]);

  document.addEventListener("keydown", function (ev) {
    if (ev.key === "/" && document.activeElement !== q) { ev.preventDefault(); q.focus(); q.select(); }
    else if (ev.key === "Escape" && document.activeElement === q) { q.value = ""; apply(); }
  });

  apply();
})();

/* Table of contents: mark the section you are actually reading.
   Runs only on document pages, which are the only pages carrying a .toc — and which only started
   loading this file at all when the wiring above was fixed. Pure enhancement: with scripting off the
   contents list is still a working set of in-page anchors, it just does not follow the reader. */
(function () {
  "use strict";
  var toc = document.querySelector(".toc");
  if (!toc) return;
  var links = {};
  [].forEach.call(toc.querySelectorAll("a"), function (a) { links[a.getAttribute("href").slice(1)] = a; });
  var heads = Object.keys(links).map(function (id) { return document.getElementById(id); }).filter(Boolean);
  if (!heads.length) return;

  /* ⛔ TWO BUGS WERE FOUND HERE THE MOMENT THE PAGES ACTUALLY LOADED THIS FILE, and both are the
     reason a feature that "exists" is not a feature that works. Recorded so neither is reintroduced.

     1. IT ASKED THE WRONG QUESTION. It lit whichever heading was INSIDE the top band right now,
        which is true only while a heading is physically crossing it. Measured on ep02's fact-check
        log: sections sit ~1,300px apart against a ~126px band, so the list was dark through nearly
        all of every section. The question is not "is a heading on the line", it is "which heading
        did I last pass" — so the active section is the LAST one whose top is above the line, and it
        stays lit until the next one passes. That is what "the section you are reading" means.

     2. AN IntersectionObserver COULD NOT SCHEDULE IT RELIABLY. It only calls back when an element's
        intersecting state CHANGES, and a heading that jumps clean over a 126px band in one frame
        never becomes intersecting, so no callback ever fires. Not theoretical: measured at 600px
        steps, the first heading went from below the band to above it with the list still showing
        nothing — and a Page Down (one viewport, ~419px) or a click on a contents link jumps far
        further than that. So the observer is no longer what ANSWERS the question — it is one of
        several things that ask it, alongside a passive scroll listener, resize, load and the font
        swap. Every one of them calls the same paint(), coalesced into a single animation frame, so
        there is exactly one place that decides which section is current and the triggers only
        decide when to re-ask. Two triggers is not the two-extractors trap fixed elsewhere in this
        file: paint() is idempotent and is the sole author of the answer. They cover each other —
        the observer misses fast jumps, and a scroll listener misses a heading that moves without
        any scrolling at all, which is exactly what the web-font swap does on first load. */
  var line = function () { return Math.max(80, window.innerHeight * 0.3); };
  function paint() {
    var y = line(), active = null;
    for (var i = 0; i < heads.length; i++) {
      if (heads[i].getBoundingClientRect().top > y) break;
      active = heads[i];
    }
    for (var id in links) links[id].classList.toggle("on", !!active && id === active.id);
  }

  var queued = false;
  function schedule() {
    if (queued) return;
    queued = true;
    (window.requestAnimationFrame || function (f) { setTimeout(f, 16); })(function () { queued = false; paint(); });
  }
  window.addEventListener("scroll", schedule, { passive: true });
  // The reading line is a fraction of the viewport height, so a resize alone can change the answer.
  window.addEventListener("resize", schedule);
  if (window.IntersectionObserver) {
    var io = new IntersectionObserver(schedule, { rootMargin: "0px 0px -70% 0px" });
    for (var oi = 0; oi < heads.length; oi++) io.observe(heads[oi]);
  }
  paint();
  /* The first paint runs before the two web faces have swapped in, and the swap moves every heading
     down the page — without this the list opens with the wrong section lit and stays that way until
     the reader scrolls. */
  window.addEventListener("load", schedule);
  if (document.fonts && document.fonts.ready && document.fonts.ready.then) document.fonts.ready.then(schedule);
})();
